# Corrected version - mark corners of all shapes
from collections import deque

output = [[7 for _ in range(17)] for _ in range(11)]

def mark_corners(grid, output, color):
    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and not visited[r][c]:
                comp = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    curr_r, curr_c = queue.popleft()
                    comp.append((curr_r, curr_c))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                rows = [x[0] for x in comp]
                cols = [x[1] for x in comp]
                if rows and cols:
                    rmin, rmax = min(rows), max(rows)
                    cmin, cmax = min(cols), max(cols)
                    output[rmin][cmin] = 9
                    output[rmin][cmax] = 9
                    output[rmax][cmin] = 9
                    output[rmax][cmax] = 9

for c in [0, 2, 3, 4, 8]:
    mark_corners(GRID_11x17, output, c)

print("Corner markers:")
for row in output:
    print(row)

{"action": "submit", "grid": output}
